"""Separate Blender entrypoint for bounded one-cut composition jobs."""

import argparse
import hashlib
import json
from pathlib import Path
import sys

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from converter.scene import SceneInputError, compose


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--job", required=True)
    args = parser.parse_args(sys.argv[sys.argv.index("--") + 1:])
    job_path = Path(args.job).resolve(strict=True)
    root = job_path.parent
    job = json.loads(job_path.read_text())
    # All file names are generated by the runner, never supplied by HTTP clients.
    paths = [root / f"person_{i}.fbx" for i in range(len(job["manifest"]["persons"]))]
    output = root / "scene.fbx"
    try:
        report = compose(job["manifest"], paths, output)
    except SceneInputError:
        (root / "report.json").write_text(json.dumps({
            "ok": False, "code": "INVALID_SCENE_FBX",
        }))
        return
    report["job_sha256"] = hashlib.sha256(job_path.read_bytes()).hexdigest()
    report["artifact_sha256"] = hashlib.sha256(output.read_bytes()).hexdigest()
    report["artifact_size"] = output.stat().st_size
    (root / "report.json").write_text(json.dumps(report, allow_nan=False))


if __name__ == "__main__":
    main()
